#include "Vrecam_shared_config_analyzer.h"
#include <cstdint>
#include <cstdlib>
#include <iostream>
static void require(bool ok, const char *message) { if (!ok) { std::cerr << message << '\n'; std::exit(1); } }
static void put_field(WData *bits, int offset, int width, std::uint32_t value) { for (int bit = 0; bit < width; ++bit) { int index = offset + bit; bits[index / 32] = (bits[index / 32] & ~(1U << (index % 32))) | (((value >> bit) & 1U) << (index % 32)); } }
static std::uint32_t get_field(const WData *bits, int offset, int width) { std::uint32_t value=0; for (int bit=0; bit<width; ++bit) { int index=offset+bit; value |= ((bits[index/32]>>(index%32))&1U)<<bit; } return value; }
int main() { Vrecam_shared_config_analyzer dut; dut.config_id_i=2; dut.pivot_valid_i=0x1f; dut.row_gt1_i=dut.row_gt2_i=dut.row_gt3_i=0; dut.col_gt1_i=dut.col_gt2_i=dut.col_gt3_i=0; dut.hybrid_valid_i=1; dut.hybrid_pointer_flat_i=0; dut.hybrid_descriptor_i=0; dut.conventional_overflow_i=0; dut.pivot_rows_flat_i = 0; for(auto &v:dut.pivot_cols_flat_i)v=0; for(auto &v:dut.hybrid_differing_flat_i)v=0; const std::uint32_t cols[5]={1,257,4095,8191,0}; const std::uint32_t edges[8]={0,31,32,255,256,257,4095,8191}; for(int i=0;i<5;++i){dut.pivot_rows_flat_i |= static_cast<QData>(10 + i) << (i * 9);put_field(dut.pivot_cols_flat_i,i*13,13,cols[i]);require(get_field(dut.pivot_cols_flat_i,i*13,13)==cols[i],"PHYSICAL_COLUMN_BOUNDARY_TEST FAIL");} for(auto edge:edges){put_field(dut.hybrid_differing_flat_i,0,13,edge);dut.eval();} put_field(dut.hybrid_differing_flat_i,0,13,1);dut.eval();auto one=dut.candidate_valid_o;put_field(dut.hybrid_differing_flat_i,0,13,257);dut.eval();require(one!=dut.candidate_valid_o,"PHYSICAL_COLUMN_ALIAS_TEST FAIL");std::cout<<"PHYSICAL_COLUMN_ALIAS_TEST PASS\nPHYSICAL_COLUMN_BOUNDARY_TEST PASS\n"; }
